# Auto-extracted quiz data

QUIZ_PL01 = [{'otazka': 'Jak narýsuješ rovnostranný trojúhelník KMS, když znáš body K a M?', 'moznosti': ['A) Změřím KM pravítkem a S odhadnu od oka', 'B) Z K i M narýsuji kružnice s poloměrem KM — jejich průsečík je bod S', 'C) Narýsuji kolmici na střed KM a S je kdekoliv na ní', 'D) Přeměřím úhel 60° a narýsuji S podle úhloměru'], 'spravna': 'B', 'vysvetleni': 'Rovnostranný trojúhelník má KS = MS = KM. Proto z K i z M narýsuji kružnici s poloměrem rovným délce KM. Kde se obě kružnice protnou — tam je bod S. Průsečíky jsou zpravidla dva = 2 řešení.'}, {'otazka': 'Co je osa úsečky AB?', 'moznosti': ['A) Přímka procházející body A a B', 'B) Rovnoběžka s úsečkou AB uprostřed stránky', 'C) Kolmice procházející středem úsečky AB', 'D) Kružnice kolem středu AB'], 'spravna': 'C', 'vysvetleni': 'Osa úsečky AB je kolmice na AB, která prochází přesně středem AB. Každý bod na ose úsečky je stejně daleko od A i od B — proto ji používáme když hledáme body, které mají být stejně daleko od dvou míst.'}, {'otazka': 'Chceš narýsovat přímku rovnoběžnou s r procházející bodem K. Jak začneš?', 'moznosti': ['A) Narýsuji kolmici na r z bodu K', 'B) Přiložím pravítko podél r, pak ho posunu na bod K a narýsuji', 'C) Narýsuji osu úsečky mezi r a bodem K', 'D) Z K narýsuji kružnici dotýkající se přímky r'], 'spravna': 'B', 'vysvetleni': 'Přiložím pravítko těsně podél přímky r. Pak — bez otáčení — ho posunu tak, aby procházelo bodem K. Narýsuji novou přímku. Takto dostanu přímku rovnoběžnou s r.'}, {'otazka': 'Kolik řešení bývá nejčastěji v úlohách kde hledáš bod na přímce?', 'moznosti': ['A) Vždy právě 1', 'B) Vždy právě 2', 'C) Zpravidla 2, ale může být 1 nebo výjimečně více', 'D) Záleží na délce kružítka'], 'spravna': 'C', 'vysvetleni': 'Nejčastěji jsou 2 řešení — bod může být na přímce na obou stranách, nebo trojúhelník může být nad i pod přímkou. Ale někdy podmínky neumožní druhé řešení. Proto vždy systematicky otestuj: existuje i zrcadlové řešení?'}, {'otazka': 'Jaký je rozdíl mezi rovnostranným a rovnoramenným trojúhelníkem?', 'moznosti': ['A) Žádný, je to totéž', 'B) Rovnostranný má všechny 3 strany stejně dlouhé, rovnoramenný má stejně dlouhé jen 2 strany', 'C) Rovnoramenný má všechny 3 strany stejně dlouhé', 'D) Rovnostranný má jen pravé úhly'], 'spravna': 'B', 'vysvetleni': 'Rovnostranný trojúhelník: KS = MS = KM — VŠECHNY tři strany jsou stejně dlouhé. Rovnoramenný trojúhelník: jen 2 strany jsou stejně dlouhé (říkáme jim ramena), třetí strana (základna) je jinak dlouhá.'}]

QUIZ_PL02 = [{'otazka': 'Díváš se na stavbu SHORA a vidíš plán 2×3 (2 řady, 3 sloupce). Co NEVÍŠ z tohoto pohledu?', 'moznosti': ['A) Kolik sloupců stavba má', 'B) Kde jsou sloupce umístěné', 'C) Jak vysoký je každý sloupec', 'D) Zda jsou sloupce vedle sebe nebo za sebou'], 'spravna': 'C', 'vysvetleni': 'Pohled shora ti říká, kde jsou sloupce — jako mapa. Ale neřekne ti, kolik kostek je v každém sloupci (= výška). Tu zjistíš až z pohledu zepředu nebo zprava.'}, {'otazka': 'Pyramida: 1. patro 5×5, 2. patro 4×4, 3. patro 3×3, 4. patro 2×2, 5. patro 1×1. Kolik kostek je úplně skrytých (neviditelných ze žádné strany)?', 'moznosti': ['A) 0', 'B) 4', 'C) 5', 'D) 16'], 'spravna': 'C', 'vysvetleni': '2. patro má 4×4 = 16 kostek. Vnitřní 2×2 = 4 kostky jsou obklopeny ze všech stran → skryté. 3. patro má 3×3 = 9 kostek. Vnitřní 1×1 = 1 kostka je skrytá. Spodní patro se dotýká podložky, takže žádná není skrytá. Celkem: 4 + 1 = 5.'}, {'otazka': 'Ze 3 kostek slepíme L-tvar (2 spoje). Kolik teček bude mít těleso, pokud chceme NEJVÍCE teček?', 'moznosti': ['A) 36', 'B) 34', 'C) 32', 'D) 24'], 'spravna': 'C', 'vysvetleni': '3 kostky × 12 teček = 36 celkem. Při každém slepení skryjeme 2 stěny — abychom ztratili co nejméně, skryjeme stěny s 1 tečkou. L-tvar má 2 spoje, každý skryje 2 stěny po 1 tečce = ztratíme 4 tečky. 36 − 4 = 32 teček.'}, {'otazka': 'Filipův model: krychle 4×4×4 z kuliček. Kolik kuliček obsahuje?', 'moznosti': ['A) 36', 'B) 48', 'C) 64', 'D) 144'], 'spravna': 'C', 'vysvetleni': 'Počet kuliček = n × n × n. Pro n = 4: 4 × 4 × 4 = 64 kuliček. (Číslo 144 je počet tyček — to je jiná otázka.)'}, {'otazka': 'Pohled zprava na stavbu má šířku 3 sloupce a výšku 2. Co to znamená?', 'moznosti': ['A) Stavba má 3 sloupce viditelných zprava', 'B) Zepředu dozadu jsou 3 řady a maximální výška stavby jsou 2 kostky', 'C) Stavba je 3 × 2 = 6 kostek celkem', 'D) Pohled shora má 3×3 políčka'], 'spravna': 'B', 'vysvetleni': 'Šířka pohledu zprava = hloubka stavby = kolik řad je zepředu dozadu = 3 řady. Výška pohledu zprava = maximální výška stavby = 2 kostky. Celkový počet kostek z tohoto pohledu nevyčteš — nevíš kolik kostek je v každé řadě.'}]

QUIZ_PL03 = [{'otazka': 'Posloupnost: 5, 11, 17, 23, 29... Jaká je 6. člen?', 'moznosti': ['A) 33', 'B) 35', 'C) 37', 'D) 41'], 'spravna': 'B', 'vysvetleni': 'Rozdíly jsou všechny +6 → přičítám vždy 6. Takže: 5, 11, 17, 23, 29, 35. Šestý člen je 35.'}, {'otazka': 'Cyklista jede 5 dní, celkem 200 km. Každý den ujede o 6 km méně než den předtím. Kolik km ujede první den?', 'moznosti': ['A) 40 km', 'B) 46 km', 'C) 52 km', 'D) 58 km'], 'spravna': 'C', 'vysvetleni': 'Kdybych každý den jel stejně (□ km), bylo by to 5×□. Ale 2.–5. den jedu celkem o 6+12+18+24 = 60 km méně. Takže 5×□ − 60 = 200 → 5×□ = 260 → □ = 52 km. Zkontroluj: 52+46+40+34+28 = 200 ✓'}, {'otazka': 'Korálky: 1. skupina = 2, každá další je 4× větší. Kolik korálků je celkem ve 4 skupinách?', 'moznosti': ['A) 80', 'B) 128', 'C) 170', 'D) 210'], 'spravna': 'C', 'vysvetleni': '1. = 2, 2. = 8, 3. = 32, 4. = 128. Celkem: 2 + 8 + 32 + 128 = 170 korálků.'}, {'otazka': 'Základní obrazec má 5 řad a 18 sloupců světlých čtverečků. Kolik tmavých čtverečků bude v rozšířeném obrazci?', 'moznosti': ['A) 18', 'B) 28', 'C) 30', 'D) 38'], 'spravna': 'C', 'vysvetleni': 'Tmavých = (šířka + 2) + 2 × výška = (18 + 2) + 2 × 5 = 20 + 10 = 30 tmavých čtverečků.'}, {'otazka': 'Šedých trojúhelníků v pásech: 1. pás = 3, 2. pás = 9, 3. pás = 15, 4. pás = 21... Kolik šedých je v 5. pásu?', 'moznosti': ['A) 24', 'B) 27', 'C) 30', 'D) 33'], 'spravna': 'B', 'vysvetleni': 'Rozdíl mezi pásy je vždy +6. Takže: 3, 9, 15, 21, 27. Pátý pás má 27 šedých trojúhelníků.'}]

